import math
    import random
    import time

    LANGUAGE_WRAPPER = 'In a math contest, let a be a positive integer and let x_1, x_2, ..., x_{n} be positive real numbers, with the cyclic convention x_{n+1} = x_1. Fix an integer m >= 2. Consider the expression\n\nE(a, x_1, ..., x_{n}) = ((16 (\\cos a)^5 - \\cos(5a)) / ({mu1} \\cos a + {mu3} \\cos(3a))) * ((\\sum_{i=1}^{n} x_i^{m} x_{i+1}^{m-1}) / (\\sum_{i=1}^{n} x_i^{2m - 1})).\n\nDetermine the maximum value of E(a, x_1, ..., x_{n}) over all such choices of a and x_i.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# We keep the Chebyshev degree at d=5 to preserve a deep identity while generalizing the inequality structure.
# For d=5, 16 x^5 - T_5(x) = 20 x^3 - 5 x = 5(T_3(x) + 2 T_1(x)),
# so 16 (cos a)^5 - cos(5a) = 5(\cos(3a) + 2\cos a).
# We parametrize the denominator as ({mu1} cos a + {mu3} cos(3a)) with (mu1, mu3) proportional to (2, 1).
# Then the trig factor becomes a constant rho = 5 * (2 cos a + cos 3a) / (mu1 cos a + mu3 cos 3a) = 5 / (mu1/2) = 10/mu1.
# Choose n and m to generalize the cyclic inequality; choose rho in {1,5} to vary difficulty.

n = rng.randint(3, 8)  # number of variables
m = rng.randint(2, 5)  # exponent parameter

rho = rng.choice([1, 5])
# For d=5, the natural coefficients are (10, 5) up to scaling by 1/rho.
# To make the trig ratio constant rho, set (mu1, mu3) = (10/rho, 5/rho).
mu1 = 10 // rho  # both choices keep mu1 integer
mu3 = 5 // rho   # both choices keep mu3 integer

# Sanity: ensure denominator isn't zero for small integer a (it never is for integer a given (2,1) proportionality,
# but we keep the generator simple and leave strict checks to the verifier).

return {"n": n, "m": m, "mu1": mu1, "mu3": mu3}

    def verifier(assign):
# Validate keys
required = ["n", "m", "mu1", "mu3"]
for k in required:
    if k not in assign:
        # Missing key
        return (False, None)
n = assign["n"]
m = assign["m"]
mu1 = assign["mu1"]
mu3 = assign["mu3"]

# Basic domain checks
try:
    n = int(n)
    m = int(m)
    mu1 = float(mu1)
    mu3 = float(mu3)
except Exception:
    # Non-numeric inputs
    return (False, None)
if not (n >= 3 and m >= 2):
    # Difficulty/validity constraints
    return (False, None)
# Coefficients must be positive
if not (mu1 > 0 and mu3 > 0):
    return (False, None)
# Enforce proportionality (to make trig factor constant): mu1:mu3 should be 2:1
rratio = mu1 / mu3
if abs(rratio - 2.0) > 1e-12:
    return (False, None)

# Check trig factor constancy across several integer a values
import math
vals = []
for a in range(1, 11):
    ca = math.cos(a)
    c3a = math.cos(3*a)
    num = 16*(ca**5) - math.cos(5*a)
    den = mu1*ca + mu3*c3a
    if abs(den) < 1e-12:
        # Extremely unlikely for integer a with (2,1) proportionality; reject to be safe
        return (False, None)
    vals.append(num/den)
# Verify all are equal within tolerance
base = vals[0]
for v in vals[1:]:
    if abs(v - base) > 1e-8:
        return (False, None)

# The cyclic inequality part
# For any positive x_i, by Young's inequality with conjugate exponents p=(2m-1)/m, q=(2m-1)/(m-1):
# x_i^m x_{i+1}^{m-1} <= x_i^{2m-1}/p + x_{i+1}^{2m-1}/q = (m/(2m-1)) x_i^{2m-1} + ((m-1)/(2m-1)) x_{i+1}^{2m-1}.
# Summing cyclically yields sum_i x_i^m x_{i+1}^{m-1} <= sum_i x_i^{2m-1}, hence the second fraction has maximum 1, attained at x_1=...=x_n.

# Therefore, the maximum of E equals the constant trig factor value.
# Compute exact rho as 10/mu1 (since mu1 = 10/rho in our generator)
rho = 10.0/mu1
# Cross-check with the numeric base value
if abs(base - rho) > 1e-8:
    return (False, None)

# Return final exact answer (rho is 1 or 5 in our generator)
return (True, rho)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

